#!/usr/bin/env bash
# SessionStart addition — security-threat-model-risk-rating.
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive $'YOU DECIDE: risk-rating methodology (per the security-threat-model proposal, section 2.2)' $'USE WHEN: rating any finding — CVSS-style qualitative severity (Critical/High/Medium/Low) is the default that rates every finding' $'PRODUCES: DREAD override permitted ONLY for architectural/trust-boundary findings that have no CVE-like vector. When DREAD is used, the row\'s rating must be immediately followed by the literal marker [dread-override] — no other placement satisfies the check' $'HAND-OFF: a row using DREAD-shaped language without the [dread-override] marker on the same row is refused by hooks/methodology-gate.sh'
